-- LinkAlive clean baseline for MySQL 8.x and MariaDB 11.x.
-- UUID values are generated by Prisma (or UUID() in the few raw-SQL writers),
-- and every DATETIME(3) value is UTC by application contract.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- CreateTable
CREATE TABLE `monitors` (
    `id` CHAR(36) NOT NULL,
    `name` VARCHAR(160) NOT NULL,
    `request_url_encrypted` BLOB NOT NULL,
    `display_url` VARCHAR(2048) NOT NULL,
    `hostname_normalized` VARCHAR(253) NOT NULL,
    `method` ENUM('GET', 'HEAD') NOT NULL DEFAULT 'GET',
    `interval_sec` INTEGER NOT NULL DEFAULT 60,
    `timeout_ms` INTEGER NOT NULL DEFAULT 10000,
    `expected_status_min` SMALLINT NOT NULL DEFAULT 200,
    `expected_status_max` SMALLINT NOT NULL DEFAULT 299,
    `expected_keyword` VARCHAR(512) NULL,
    `follow_redirects` BOOLEAN NOT NULL DEFAULT true,
    `max_redirects` SMALLINT NOT NULL DEFAULT 5,
    `failure_threshold` SMALLINT NOT NULL DEFAULT 3,
    `recovery_threshold` SMALLINT NOT NULL DEFAULT 2,
    `lifecycle_status` ENUM('ACTIVE', 'PAUSED', 'DELETED') NOT NULL DEFAULT 'ACTIVE',
    `health_state` ENUM('PENDING', 'UP', 'SUSPECT', 'DOWN', 'RECOVERING') NOT NULL DEFAULT 'PENDING',
    `consecutive_failures` INTEGER NOT NULL DEFAULT 0,
    `consecutive_successes` INTEGER NOT NULL DEFAULT 0,
    `failure_streak_started_at` DATETIME(3) NULL,
    `failure_streak_first_error_type` ENUM('DNS_ERROR', 'CONNECT_TIMEOUT', 'CONNECTION_REFUSED', 'TLS_ERROR', 'TTFB_TIMEOUT', 'REQUEST_TIMEOUT', 'REDIRECT_ERROR', 'HTTP_STATUS_MISMATCH', 'CONTENT_MISMATCH', 'RESPONSE_LIMIT_EXCEEDED', 'NETWORK_ERROR', 'PLATFORM_ERROR') NULL,
    `last_checked_at` DATETIME(3) NULL,
    `last_success_at` DATETIME(3) NULL,
    `last_failure_at` DATETIME(3) NULL,
    `last_status_code` SMALLINT NULL,
    `last_ttfb_ms` INTEGER NULL,
    `last_total_ms` INTEGER NULL,
    `last_error_type` ENUM('DNS_ERROR', 'CONNECT_TIMEOUT', 'CONNECTION_REFUSED', 'TLS_ERROR', 'TTFB_TIMEOUT', 'REQUEST_TIMEOUT', 'REDIRECT_ERROR', 'HTTP_STATUS_MISMATCH', 'CONTENT_MISMATCH', 'RESPONSE_LIMIT_EXCEEDED', 'NETWORK_ERROR', 'PLATFORM_ERROR') NULL,
    `next_check_at` DATETIME(3) NULL,
    `config_version` INTEGER NOT NULL DEFAULT 1,
    `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updated_at` DATETIME(3) NOT NULL,
    `deleted_at` DATETIME(3) NULL,

    INDEX `monitors_due_idx`(`lifecycle_status`, `next_check_at`),
    INDEX `monitors_health_idx`(`health_state`),
    INDEX `monitors_hostname_idx`(`hostname_normalized`),
    INDEX `monitors_deleted_at_idx`(`deleted_at`),
    PRIMARY KEY (`id`),
    CONSTRAINT `monitors_required_text_check` CHECK (
      CHAR_LENGTH(TRIM(`name`)) > 0
      AND OCTET_LENGTH(`request_url_encrypted`) > 0
      AND CHAR_LENGTH(TRIM(`display_url`)) > 0
      AND CHAR_LENGTH(TRIM(`hostname_normalized`)) > 0
    ),
    CONSTRAINT `monitors_interval_check` CHECK (`interval_sec` IN (60, 300, 600, 1800, 3600)),
    CONSTRAINT `monitors_timeout_check` CHECK (`timeout_ms` BETWEEN 1000 AND 30000),
    CONSTRAINT `monitors_expected_status_check` CHECK (
      `expected_status_min` BETWEEN 100 AND 599
      AND `expected_status_max` BETWEEN 100 AND 599
      AND `expected_status_min` <= `expected_status_max`
    ),
    CONSTRAINT `monitors_keyword_method_check` CHECK (`method` <> 'HEAD' OR `expected_keyword` IS NULL),
    CONSTRAINT `monitors_thresholds_check` CHECK (
      `max_redirects` BETWEEN 0 AND 5
      AND `failure_threshold` BETWEEN 1 AND 10
      AND `recovery_threshold` BETWEEN 1 AND 10
    ),
    CONSTRAINT `monitors_state_counts_check` CHECK (
      `consecutive_failures` >= 0 AND `consecutive_successes` >= 0 AND `config_version` >= 1
    ),
    CONSTRAINT `monitors_last_measurements_check` CHECK (
      (`last_status_code` IS NULL OR `last_status_code` BETWEEN 100 AND 999)
      AND (`last_ttfb_ms` IS NULL OR `last_ttfb_ms` >= 0)
      AND (`last_total_ms` IS NULL OR `last_total_ms` >= 0)
    ),
    CONSTRAINT `monitors_deleted_lifecycle_check` CHECK (
      (`lifecycle_status` = 'DELETED' AND `deleted_at` IS NOT NULL)
      OR (`lifecycle_status` <> 'DELETED' AND `deleted_at` IS NULL)
    )
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

