CREATE TABLE `scheduled_checks` (
    `id` CHAR(36) NOT NULL,
    `monitor_id` CHAR(36) NOT NULL,
    `scheduled_at` DATETIME(3) NOT NULL,
    `config_version` INTEGER NOT NULL,
    `status` ENUM('PENDING', 'ENQUEUED', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELED') NOT NULL DEFAULT 'PENDING',
    `lease_owner` VARCHAR(160) NULL,
    `lease_until` DATETIME(3) NULL,
    `queue_job_id` VARCHAR(160) NULL,
    `attempt_count` INTEGER NOT NULL DEFAULT 0,
    `failure_reason_safe` VARCHAR(1024) NULL,
    `enqueued_at` DATETIME(3) NULL,
    `started_at` DATETIME(3) NULL,
    `completed_at` DATETIME(3) NULL,
    `canceled_at` DATETIME(3) NULL,
    `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updated_at` DATETIME(3) NOT NULL,
    `active_monitor_id` VARCHAR(36)
      GENERATED ALWAYS AS (
        CASE
          WHEN `status` IN ('PENDING', 'ENQUEUED', 'RUNNING') THEN RTRIM(`monitor_id`)
          ELSE NULL
        END
      ) STORED,

    INDEX `scheduled_checks_reconcile_idx`(`status`, `lease_until`),
    INDEX `scheduled_checks_monitor_created_idx`(`monitor_id`, `created_at` DESC),
    UNIQUE INDEX `scheduled_checks_schedule_key`(`monitor_id`, `scheduled_at`, `config_version`),
    UNIQUE INDEX `scheduled_checks_result_identity_key`(`id`, `monitor_id`, `config_version`),
    UNIQUE INDEX `scheduled_checks_one_active_per_monitor_idx`(`active_monitor_id`),
    INDEX `scheduled_checks_retention_terminal_idx`(`status`, `completed_at`, `canceled_at`, `updated_at`, `id`),
    PRIMARY KEY (`id`),
    CONSTRAINT `scheduled_checks_config_version_check` CHECK (`config_version` >= 1),
    CONSTRAINT `scheduled_checks_attempt_count_check` CHECK (`attempt_count` >= 0),
    CONSTRAINT `scheduled_checks_lease_pair_check` CHECK (
      (`lease_owner` IS NULL AND `lease_until` IS NULL)
      OR (`lease_owner` IS NOT NULL AND `lease_until` IS NOT NULL)
    )
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- CreateTable
CREATE TABLE `check_results` (
    `id` CHAR(36) NOT NULL,
    `monitor_id` CHAR(36) NULL,
    `scheduled_check_id` CHAR(36) NULL,
    `source` ENUM('SCHEDULED', 'MANUAL', 'TEST') NOT NULL,
    `outcome` ENUM('SUCCESS', 'TARGET_FAILURE', 'PLATFORM_ERROR', 'INCONCLUSIVE') NOT NULL,
    `config_version` INTEGER NULL,
    `display_url_snapshot` VARCHAR(2048) NOT NULL,
    `started_at` DATETIME(3) NOT NULL,
    `finished_at` DATETIME(3) NOT NULL,
    `status_code` SMALLINT NULL,
    `ttfb_ms` INTEGER NULL,
    `total_ms` INTEGER NOT NULL,
    `error_type` ENUM('DNS_ERROR', 'CONNECT_TIMEOUT', 'CONNECTION_REFUSED', 'TLS_ERROR', 'TTFB_TIMEOUT', 'REQUEST_TIMEOUT', 'REDIRECT_ERROR', 'HTTP_STATUS_MISMATCH', 'CONTENT_MISMATCH', 'RESPONSE_LIMIT_EXCEEDED', 'NETWORK_ERROR', 'PLATFORM_ERROR') NULL,
    `error_message_safe` VARCHAR(1024) NULL,
    `worker_region` VARCHAR(80) NULL,
    `redirect_count` SMALLINT NOT NULL DEFAULT 0,
    `response_bytes_read` INTEGER NULL,
    `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    INDEX `check_results_monitor_started_idx`(`monitor_id`, `started_at` DESC),
    INDEX `check_results_outcome_started_idx`(`outcome`, `started_at`),
    INDEX `check_results_retention_idx`(`created_at`),
    UNIQUE INDEX `check_results_scheduled_identity_key`(`scheduled_check_id`, `monitor_id`, `config_version`),
    INDEX `check_results_retention_finished_idx`(`finished_at`, `id`),
    PRIMARY KEY (`id`),
    CONSTRAINT `check_results_source_ledger_check` CHECK (
      (
        `source` = 'SCHEDULED' AND `monitor_id` IS NOT NULL
        AND `scheduled_check_id` IS NOT NULL AND `config_version` IS NOT NULL
      )
      OR (
        `source` = 'MANUAL' AND `monitor_id` IS NOT NULL
        AND `scheduled_check_id` IS NULL AND `config_version` IS NOT NULL
      )
      OR (
        `source` = 'TEST' AND `monitor_id` IS NULL
        AND `scheduled_check_id` IS NULL AND `config_version` IS NULL
      )
    ),
    CONSTRAINT `check_results_display_snapshot_check` CHECK (CHAR_LENGTH(TRIM(`display_url_snapshot`)) > 0),
    CONSTRAINT `check_results_timing_check` CHECK (
      `finished_at` >= `started_at` AND `total_ms` >= 0
      AND (`ttfb_ms` IS NULL OR `ttfb_ms` >= 0)
    ),
    CONSTRAINT `check_results_status_code_check` CHECK (`status_code` IS NULL OR `status_code` BETWEEN 100 AND 999),
    CONSTRAINT `check_results_counts_check` CHECK (
      `redirect_count` BETWEEN 0 AND 5
      AND (`response_bytes_read` IS NULL OR `response_bytes_read` >= 0)
    ),
    CONSTRAINT `check_results_config_version_check` CHECK (`config_version` IS NULL OR `config_version` >= 1),
    CONSTRAINT `check_results_success_error_check` CHECK (`outcome` <> 'SUCCESS' OR `error_type` IS NULL),
    CONSTRAINT `check_results_target_error_check` CHECK (
      `outcome` <> 'TARGET_FAILURE'
      OR (`error_type` IS NOT NULL AND `error_type` <> 'PLATFORM_ERROR')
    ),
    CONSTRAINT `check_results_platform_error_check` CHECK (
      `outcome` <> 'PLATFORM_ERROR' OR `error_type` = 'PLATFORM_ERROR'
    )
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- CreateTable
CREATE TABLE `incidents` (
    `id` CHAR(36) NOT NULL,
    `monitor_id` CHAR(36) NOT NULL,
    `config_version` INTEGER NOT NULL,
    `status` ENUM('OPEN', 'RESOLVED', 'CANCELED') NOT NULL DEFAULT 'OPEN',
    `first_failure_at` DATETIME(3) NOT NULL,
    `detected_at` DATETIME(3) NOT NULL,
    `resolved_at` DATETIME(3) NULL,
    `canceled_at` DATETIME(3) NULL,
    `first_error_type` ENUM('DNS_ERROR', 'CONNECT_TIMEOUT', 'CONNECTION_REFUSED', 'TLS_ERROR', 'TTFB_TIMEOUT', 'REQUEST_TIMEOUT', 'REDIRECT_ERROR', 'HTTP_STATUS_MISMATCH', 'CONTENT_MISMATCH', 'RESPONSE_LIMIT_EXCEEDED', 'NETWORK_ERROR', 'PLATFORM_ERROR') NULL,
    `last_error_type` ENUM('DNS_ERROR', 'CONNECT_TIMEOUT', 'CONNECTION_REFUSED', 'TLS_ERROR', 'TTFB_TIMEOUT', 'REQUEST_TIMEOUT', 'REDIRECT_ERROR', 'HTTP_STATUS_MISMATCH', 'CONTENT_MISMATCH', 'RESPONSE_LIMIT_EXCEEDED', 'NETWORK_ERROR', 'PLATFORM_ERROR') NULL,
    `closure_reason` ENUM('RECOVERED', 'PAUSED', 'DELETED', 'CONFIG_CHANGED') NULL,
    `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updated_at` DATETIME(3) NOT NULL,
    `open_monitor_id` VARCHAR(36)
      GENERATED ALWAYS AS (
        CASE WHEN `status` = 'OPEN' THEN RTRIM(`monitor_id`) ELSE NULL END
      ) STORED,

    INDEX `incidents_monitor_detected_idx`(`monitor_id`, `detected_at` DESC),
    INDEX `incidents_status_detected_idx`(`status`, `detected_at` DESC),
    UNIQUE INDEX `incidents_one_open_per_monitor_idx`(`open_monitor_id`),
    INDEX `incidents_retention_closed_idx`(`status`, `resolved_at`, `canceled_at`, `id`),
    PRIMARY KEY (`id`),
    CONSTRAINT `incidents_config_version_check` CHECK (`config_version` >= 1),
    CONSTRAINT `incidents_detection_order_check` CHECK (`first_failure_at` <= `detected_at`),
    CONSTRAINT `incidents_closure_check` CHECK (
      (`status` = 'OPEN' AND `resolved_at` IS NULL AND `canceled_at` IS NULL AND `closure_reason` IS NULL)
      OR (
        `status` = 'RESOLVED' AND `resolved_at` IS NOT NULL
        AND `resolved_at` >= `detected_at` AND `canceled_at` IS NULL
        AND `closure_reason` = 'RECOVERED'
      )
      OR (
        `status` = 'CANCELED' AND `canceled_at` IS NOT NULL
        AND `canceled_at` >= `detected_at` AND `resolved_at` IS NULL
        AND `closure_reason` IN ('PAUSED', 'DELETED', 'CONFIG_CHANGED')
      )
    )
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

