    PRIMARY KEY (`id`),
    CONSTRAINT `notification_outbox_sequence_check` CHECK (
      (`event_type` IN ('DOWN', 'TEST') AND `sequence` = 1)
      OR (`event_type` IN ('RECOVERY', 'RESOLVED_SUMMARY') AND `sequence` = 2)
    ),
    CONSTRAINT `notification_outbox_incident_check` CHECK (
      (`event_type` = 'TEST' AND `incident_id` IS NULL)
      OR (`event_type` <> 'TEST' AND `incident_id` IS NOT NULL)
    ),
    CONSTRAINT `notification_outbox_attempts_check` CHECK (
      `attempt_count` >= 0 AND `max_attempts` BETWEEN 1 AND 10 AND `attempt_count` <= `max_attempts`
    ),
    CONSTRAINT `notification_outbox_lease_pair_check` CHECK (
      (`lease_owner` IS NULL AND `lease_until` IS NULL)
      OR (`lease_owner` IS NOT NULL AND `lease_until` IS NOT NULL)
    ),
    CONSTRAINT `notification_outbox_required_check` CHECK (
